class Solution {
  public int numberOfPatterns(int m, int n) {
    int[][] skip = new int[10][10]; // the key that must already be used to jump between two keys
    skip[1][3] = skip[3][1] = 2;
    skip[4][6] = skip[6][4] = 5;
    skip[7][9] = skip[9][7] = 8;
    skip[1][7] = skip[7][1] = 4;
    skip[2][8] = skip[8][2] = 5;
    skip[3][9] = skip[9][3] = 6;
    skip[1][9] = skip[9][1] = skip[3][7] = skip[7][3] = 5;
    boolean[] used = new boolean[10];
    // corners and edges are symmetric
    return 4 * count(1, 1, m, n, skip, used) + 4 * count(2, 1, m, n, skip, used) + count(5, 1, m, n, skip, used);
  }

  private int count(int cur, int len, int m, int n, int[][] skip, boolean[] used) {
    int total = len >= m ? 1 : 0;
    if (len == n) return total;
    used[cur] = true;
    for (int next = 1; next <= 9; next++) {
      if (used[next] || (skip[cur][next] != 0 && !used[skip[cur][next]])) continue;
      total += count(next, len + 1, m, n, skip, used);
    }
    used[cur] = false;
    return total;
  }
}
